fn greater(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Both vectors are assumed to have the same length.
    // Iterate over them in lockstep, compare each pair (after promoting to i32),
    // and collect the boolean results into a new Vec<bool>.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| (x as i32) > (y as i32))
     .collect()
}

